CREATE TYPE "UserStatus" AS ENUM ('ACTIVE','INACTIVE');
CREATE TYPE "IdentityProvider" AS ENUM ('GOOGLE','WHATSAPP_PHONE');
CREATE TYPE "AssignmentType" AS ENUM ('OWNER','INSTRUCTOR');
CREATE TYPE "OutboxStatus" AS ENUM ('PENDING','PUBLISHED','FAILED');
CREATE TABLE "User" ("id" UUID PRIMARY KEY,"displayName" TEXT NOT NULL,"status" "UserStatus" NOT NULL DEFAULT 'ACTIVE',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "Identity" ("id" UUID PRIMARY KEY,"userId" UUID NOT NULL,"provider" "IdentityProvider" NOT NULL,"subjectHash" TEXT NOT NULL,"verifiedAt" TIMESTAMP(3) NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "Identity_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE RESTRICT);
CREATE UNIQUE INDEX "Identity_provider_subjectHash_key" ON "Identity"("provider","subjectHash"); CREATE INDEX "Identity_userId_idx" ON "Identity"("userId");
CREATE TABLE "Branch" ("id" UUID PRIMARY KEY,"code" TEXT NOT NULL,"name" TEXT NOT NULL,"timezone" TEXT NOT NULL,"active" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP); CREATE UNIQUE INDEX "Branch_code_key" ON "Branch"("code");
CREATE TABLE "Assignment" ("id" UUID PRIMARY KEY,"userId" UUID NOT NULL,"branchId" UUID NOT NULL,"type" "AssignmentType" NOT NULL,"activeFrom" DATE NOT NULL,"activeUntil" DATE,"version" INTEGER NOT NULL DEFAULT 0,CONSTRAINT "Assignment_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE RESTRICT,CONSTRAINT "Assignment_branchId_fkey" FOREIGN KEY ("branchId") REFERENCES "Branch"("id") ON DELETE RESTRICT,CONSTRAINT "Assignment_effective_range" CHECK ("activeUntil" IS NULL OR "activeUntil" >= "activeFrom")); CREATE INDEX "Assignment_userId_activeFrom_activeUntil_idx" ON "Assignment"("userId","activeFrom","activeUntil"); CREATE INDEX "Assignment_branchId_type_activeFrom_activeUntil_idx" ON "Assignment"("branchId","type","activeFrom","activeUntil");
CREATE TABLE "AuditLog" ("id" UUID PRIMARY KEY,"occurredAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"actorType" TEXT NOT NULL,"actorId" UUID,"branchId" UUID,"action" TEXT NOT NULL,"objectType" TEXT NOT NULL,"objectId" TEXT NOT NULL,"beforeMasked" JSONB,"afterMasked" JSONB,"correlationId" TEXT NOT NULL); CREATE INDEX "AuditLog_branchId_occurredAt_idx" ON "AuditLog"("branchId","occurredAt"); CREATE INDEX "AuditLog_objectType_objectId_occurredAt_idx" ON "AuditLog"("objectType","objectId","occurredAt");
CREATE TABLE "IdempotencyRecord" ("id" UUID PRIMARY KEY,"scope" TEXT NOT NULL,"keyHash" TEXT NOT NULL,"requestHash" TEXT NOT NULL,"responseStatus" INTEGER,"responseBody" JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"expiresAt" TIMESTAMP(3) NOT NULL); CREATE UNIQUE INDEX "IdempotencyRecord_scope_keyHash_key" ON "IdempotencyRecord"("scope","keyHash"); CREATE INDEX "IdempotencyRecord_expiresAt_idx" ON "IdempotencyRecord"("expiresAt");
CREATE TABLE "OutboxEvent" ("id" UUID PRIMARY KEY,"eventType" TEXT NOT NULL,"aggregateType" TEXT NOT NULL,"aggregateId" TEXT NOT NULL,"payload" JSONB NOT NULL,"correlationId" TEXT NOT NULL,"status" "OutboxStatus" NOT NULL DEFAULT 'PENDING',"occurredAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"publishedAt" TIMESTAMP(3),"attempts" INTEGER NOT NULL DEFAULT 0); CREATE INDEX "OutboxEvent_status_occurredAt_idx" ON "OutboxEvent"("status","occurredAt"); CREATE INDEX "OutboxEvent_aggregateType_aggregateId_idx" ON "OutboxEvent"("aggregateType","aggregateId");
CREATE TABLE "EffectiveConfiguration" ("id" UUID PRIMARY KEY,"kind" TEXT NOT NULL,"businessKey" TEXT NOT NULL,"branchId" UUID,"value" JSONB NOT NULL,"effectiveFrom" TIMESTAMP(3) NOT NULL,"effectiveUntil" TIMESTAMP(3),"approvedEvidence" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "EffectiveConfiguration_branchId_fkey" FOREIGN KEY ("branchId") REFERENCES "Branch"("id") ON DELETE RESTRICT,CONSTRAINT "EffectiveConfiguration_effective_range" CHECK ("effectiveUntil" IS NULL OR "effectiveUntil" > "effectiveFrom")); CREATE INDEX "EffectiveConfiguration_kind_businessKey_effectiveFrom_effectiveUntil_idx" ON "EffectiveConfiguration"("kind","businessKey","effectiveFrom","effectiveUntil"); CREATE INDEX "EffectiveConfiguration_branchId_kind_effectiveFrom_idx" ON "EffectiveConfiguration"("branchId","kind","effectiveFrom");
